 51  // AsyncRendererComponentFn
 52  async function renderToStaticMarkup(
 53  	this: RendererContext,
 54  	Component: any,
 55  	props: Record<string, any>,
 56  	{ default: children, ...slotted }: any,
 57  	metadata?: Record<string, any>,
 58  ) {
 59  	const ctx = getContext(this.result);
 60  	const renderId = metadata?.hydrate ? incrementId(ctx) : '';
 61  	const needsHydrate = metadata?.astroStaticSlot ? !!metadata.hydrate : true;
 62  	const tagName = needsHydrate ? 'astro-slot' : 'astro-static-slot';
 63  
 64  	const renderStrategy = (metadata?.renderStrategy ?? 'async') as RenderStrategy;
 65  
 66  	const renderFn = () => {
 67  		const slots: Record<string, any> = {};
 68  		for (const [key, value] of Object.entries(slotted)) {
 69  			const name = slotName(key);
 70> 			slots[name] = ssr(`<${tagName} name="${name}">${value}</${tagName}>`);
 71  		}
 72  		// Note: create newProps to avoid mutating `props` before they are serialized
 73  		const newProps = {
 74  			...props,
 75  			...slots,
 76  			// In Solid SSR mode, `ssr` creates the expected structure for `children`.
 77  			children: children != null ? ssr(`<${tagName}>${children}</${tagName}>`) : children,
 78  		};
 79  
 80  		if (renderStrategy === 'sync') {
 81  			// Sync Render:
 82  			// <Component />
 83  			// This render mode is not exposed directly to the end user. It is only
 84  			// used in the check() function.
 85  			return createComponent(Component, newProps);
 86  		} else {
 87  			if (needsHydrate) {
 88  				// Hydrate + Async Render:
 89  				// <Suspense>
 90  				//   <Component />
 91  				// </Suspense>
 92  				return createComponent(Suspense, {
 93  					get children() {
 94  						return createComponent(Component, newProps);
 95  					},
 96  				});
 97  			} else {
 98  				// Static + Async Render
 99  				// <NoHydration>
100  				//   <Suspense>
101  				//     <Component />
102  				// 	 </Suspense>
103  				// </NoHydration>
104  				return createComponent(NoHydration, {
105  					get children() {
106  						return createComponent(Suspense, {
107  							get children() {
108  								return createComponent(Component, newProps);
109  							},
110  						});

