321    private async getSystemdServiceInfo(
322      serviceName: string
323    ): Promise<ServiceInfo> {
324      const { stdout } = await execAsync(
325        `systemctl show ${serviceName} --no-pager`
326      );
327  
328      const properties: Record<string, string> = {};
329      stdout.split('\n').forEach((line) => {
330        const [key, value] = line.split('=');
331        if (key && value) {
332          properties[key] = value;
333        }
334      });
335  
336      const status: ServiceStatus =
337        properties.ActiveState === 'active'
338          ? 'active'
339          : properties.ActiveState === 'inactive'
340            ? 'inactive'
341            : 'failed';
342  
343      const info: ServiceInfo = {
344        name: serviceName,
345        type: 'systemd',
346        status,
347        enabled: properties.UnitFileState === 'enabled',
348        pid: properties.MainPID ? parseInt(properties.MainPID) : undefined,
349        lastStartTime: properties.ExecMainStartTimestamp
350          ? Date.parse(properties.ExecMainStartTimestamp)
351          : undefined,
352      };
353  
354      // Get dependencies
355      try {
356        const { stdout: depsOut } = await execAsync(
357>         `systemctl list-dependencies ${serviceName} --plain --no-pager`
358        );
