743    protected async restoreSchema(
744      srcSchema: string,
745      targetSchema: string,
746      pgRestoreCommand: string,
747      toolchain: DBBackupToolchain = this.backupToolchain,
748    ) {
749      const { username, host, port, database, password } = this.dbOpts;
750      const ts = Date.now();
751      // 1. backup current schema to srcSchema_ts if exists and create new schema (same name as srcSchema)
752      const sqlCommandName = this.getSqlCommandName(toolchain);
753      const preCommand = `${sqlCommandName} -U ${username} -h ${host} ${port ? `-p ${port}` : ''} -d ${database} -c "
754      DO ${D$$}
755      BEGIN
756          IF EXISTS (SELECT 1 FROM information_schema.schemata WHERE schema_name = '${srcSchema}') THEN
757              EXECUTE 'ALTER SCHEMA ${srcSchema} RENAME TO ${srcSchema}_${ts}';
758          END IF;
759          EXECUTE 'CREATE SCHEMA ${srcSchema}';
760      END ${D$$};"`.replace(/\n/g, ' ');
761      const postCommand = `${sqlCommandName} -U ${username} -h ${host} ${port ? `-p ${port}` : ''} -d ${database} -c "
762      DO ${D$$}
763      BEGIN
764          EXECUTE 'DROP SCHEMA ${targetSchema} CASCADE';
765          EXECUTE 'ALTER SCHEMA ${srcSchema} RENAME TO ${targetSchema}';
766          IF EXISTS (SELECT 1 FROM information_schema.schemata WHERE schema_name = '${srcSchema}_${ts}') THEN
767              EXECUTE 'ALTER SCHEMA ${srcSchema}_${ts} RENAME TO ${srcSchema}';
768          END IF;
769      END ${D$$};"`.replace(/\n/g, ' ');
770  
771      await run(preCommand, this.getPasswordEnvVars(password, toolchain));
772      try {
773        await run(pgRestoreCommand, this.getPasswordEnvVars(password, toolchain));
774      } finally {
775>       await run(postCommand, this.getPasswordEnvVars(password, toolchain));
776      }
777      await this.syncCollectionSchemaMetadata(srcSchema, targetSchema, toolchain);
778    }
779  
780    protected async syncCollectionSchemaMetadata(
781      srcSchema: string,
782      targetSchema: string,
783      toolchain: DBBackupToolchain = this.backupToolchain,
784    ) {
785      const { username, host, port, database, password, tablePrefix } = this.dbOpts;
786      const collectionsTable = `${tablePrefix || ''}collections`;
787      const targetSchemaLiteral = escapeStringLiteral(targetSchema);
788      const srcSchemaLiteral = escapeStringLiteral(srcSchema);
789      const collectionsTableLiteral = escapeStringLiteral(collectionsTable);
790      const updateCollectionSchemaCommand = `${this.getSqlCommandName(toolchain)} -U ${username} -h ${host} ${
791        port ? `-p ${port}` : ''
792      } -d ${database} -c "
793      DO ${D$$}
794      DECLARE
795          collections_table text := '${collectionsTableLiteral}';
796      BEGIN
797          IF EXISTS (
798              SELECT 1 FROM information_schema.columns
799              WHERE table_schema = '${targetSchemaLiteral}'
800                AND table_name = collections_table
801                AND column_name = 'options'
802          ) THEN
803              EXECUTE format(
804                'UPDATE %I.%I SET options = jsonb_set(options::jsonb, ''{schema}'', to_jsonb(%L::text), true) WHERE options->>''schema'' = %L',
805                '${targetSchemaLiteral}',
806                collections_table,
807                '${targetSchemaLiteral}',
808                '${srcSchemaLiteral}'
809              );
810          END IF;
811      END ${D$$};"`.replace(/\n/g, ' ');
812      await run(updateCollectionSchemaCommand, this.getPasswordEnvVars(password, toolchain));
813    }
814  }
