451    private getLastCommit(branch: string, cwd: string): BranchInfo['lastCommit'] {
452      try {
453        const format = '%H%x00%h%x00%an%x00%aI%x00%s';
454        const output = execSync(`git log -1 --format="${format}" ${branch}`, {
455          cwd,
456          encoding: 'utf-8',
